package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * A new DRAFT claim, dated (when left undated) the sheet's entry date while it is set, else its today, its due-by fixed now: the terms-th business day after its date
 * (skipping Saturdays, Sundays and the holidays on the sheet now), its terms its person's own, else those of their grade on that date, else the sheet's.
 * Due by a date inside a soft-closed period (its period is the one containing its due-by), it is a late entry.
 */
public class BuildClaim {
    public void build(@Val ClaimInput input, @Val Sheet sheet, @Val Person person, SettingsRepository settings,
            PeriodRepository periods, HolidayRepository holidays,
            Out<Claim> claimOut) {
        Settings terms = settings.find(sheet.id());
        LocalDate date = input.date() == null ? terms.entryDay(sheet.today()) : input.date();
        Claim claim = new Claim(null, sheet.id(), person.getId(), input.amount(), date, input.note(),
                ClaimStatus.DRAFT, null, null, null);
        claim.setCorrects(input.corrects());
        claim.setRef(input.ref());
        claim.setTags(input.tags());
        claim.setDueBy(holidays.dueBy(sheet.id(), date, terms.termsFor(person, date)));
        claim.setLateEntry(periods.softClosedOn(sheet.id(), claim.getDueBy()) != null);
        claimOut.set(claim);
    }
}
        Settings terms = settings.find(sheet.id());
        List<Person> persons = new ArrayList<>();
        List<Claim> built = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        for (PasteLine line : paste.lines()) {
            Person person = people.findByName(sheet.id(), line.name());
            if (person == null) throw new InvalidClaimException("No one named " + line.name() + " is on the sheet");
            LocalDate date = line.claim().date() == null ? terms.entryDay(sheet.today()) : line.claim().date();
            Claim claim = new Claim(null, sheet.id(), person.getId(), line.claim().amount(), date, line.claim().note(),
                    ClaimStatus.DRAFT, null, null, null);
            claim.setRef(line.claim().ref());
            if (claim.getRef() != null && !refs.add(claim.getRef().toUpperCase(Locale.ROOT))) {
                throw new InvalidClaimException("The reference " + claim.getRef() + " is pasted more than once");
            }
            new CheckClaimRef().check(claim, claims);
            claim.setDueBy(holidays.dueBy(sheet.id(), date, terms.termsFor(person, date)));
            new CheckClaimPeriod().check(sheet, claim, periods);
            claim.setLateEntry(periods.softClosedOn(sheet.id(), claim.getDueBy()) != null);
            new CheckClaimRetired().check(sheet, claim, people);
            persons.add(person);
            built.add(claim);
        }
        String user = Audit.user(request);
        for (int i = 0; i < built.size(); i++) {
            Claim claim = built.get(i);
            claims.save(claim);
            log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
            new AuditClaimAdded().audit(sheet, persons.get(i), claim, request, audit);
        }
        result.set(new PasteResponse(built.size()));
    }
            SettingsRepository settingsRepository, PersonRepository people, PeriodRepository periods, HolidayRepository holidays, HttpServletRequest request,
            Out<Split> splitOut) throws InvalidClaimStatusException, InvalidClaimException {
        String user = Audit.user(request);
        String role = roles.roleOf(sheet.id(), user);
        Settings settings = settingsRepository.find(sheet.id());
        if (!settings.allows("open", role)) {
            throw new InvalidClaimStatusException("A " + role + " may not split a claim");
        }
        claim.split(split.amount(), sheet.today());
        Person person = people.find(sheet.id(), claim.getPersonId());
        Claim made = new Claim(null, sheet.id(), claim.getPersonId(), split.amount(), claim.getDate(),
                claim.getNote(), ClaimStatus.OPEN, null, null, user);
        made.setSplitFrom(claim.getNumber());
        made.setTags(claim.getTags());
        made.setDueBy(holidays.dueBy(sheet.id(), claim.getDate(), settings.termsFor(person, claim.getDate())));
        made.setLateEntry(periods.softClosedOn(sheet.id(), made.getDueBy()) != null);
        splitOut.set(new Split(made));
    }
}
